constraints:
1 ≤ Number of Nodes ≤ 10^{5}

expected time complexity: O(M+N) where M and N are the sizes of the two BSTs.
expected auxiliary space: O(Height of BST1 + Height of BST2 + M + N(for storing the answer)).

standard_solution_code:
class Solution:

	def merge(self, root1, root2):
		req = []
		(lst1, lst2) = ([], [])
		while root1:
			lst1.append(root1)
			root1 = root1.left
		while root2:
			lst2.append(root2)
			root2 = root2.left
		(x, y) = (get(lst1), get(lst2))
		while x and y:
			if x.data > y.data:
				req.append(y.data)
				y = get(lst2)
			else:
				req.append(x.data)
				x = get(lst1)
		while x:
			req.append(x.data)
			x = get(lst1)
		while y:
			req.append(y.data)
			y = get(lst2)
		return req

def get(lst):
	if not lst:
		return None
	x = lst.pop()
	if x.right:
		temp = x.right
		while temp:
			lst.append(temp)
			temp = temp.left
	return x
